import unittest
from solution import calculate_discount

class TestDiscount(unittest.TestCase):
    def test_normal(self):
        self.assertEqual(calculate_discount(100, "normal"), 100.00)

    def test_silver(self):
        self.assertEqual(calculate_discount(100, "silver"), 95.00)

    def test_gold_campaign(self):
        self.assertEqual(calculate_discount(100, "gold", True), 81.00)

    def test_rounding(self):
        self.assertEqual(calculate_discount(99.99, "silver"), 94.99)

    def test_negative(self):
        with self.assertRaises(ValueError):
            calculate_discount(-1, "normal")

    def test_invalid_level(self):
        with self.assertRaises(ValueError):
            calculate_discount(100, "vip")

if __name__ == "__main__":
    unittest.main()

import unittest
from solution import compare_versions

class TestVersions(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(compare_versions("1.2.0", "1.1.9"), 1)
        self.assertEqual(compare_versions("1.0", "1.0.0"), 0)
        self.assertEqual(compare_versions("2.0", "10.0"), -1)

    def test_leading_zero(self):
        self.assertEqual(compare_versions("01.002", "1.2.0"), 0)

    def test_invalid(self):
        for value in ["", "1..2", "1.a", "-1.0", ".1", "1."]:
            with self.assertRaises(ValueError):
                compare_versions(value, "1.0")

if __name__ == "__main__":
    unittest.main()

import unittest
from solution import deep_merge

class TestMerge(unittest.TestCase):
    def test_recursive(self):
        base = {"db": {"host": "a", "ports": [1]}, "debug": False}
        override = {"db": {"host": "b"}, "debug": True}
        result = deep_merge(base, override)
        self.assertEqual(result, {"db": {"host": "b", "ports": [1]}, "debug": True})

    def test_no_mutation_or_sharing(self):
        base = {"x": {"items": [1, 2]}}
        override = {"y": {"items": [3]}}
        result = deep_merge(base, override)
        result["x"]["items"].append(9)
        result["y"]["items"].append(8)
        self.assertEqual(base, {"x": {"items": [1, 2]}})
        self.assertEqual(override, {"y": {"items": [3]}})

    def test_override_scalar(self):
        self.assertEqual(deep_merge({"a": {"x": 1}}, {"a": 2}), {"a": 2})

if __name__ == "__main__":
    unittest.main()
